}

.close-btn:active { transform: scale(0.93); }

.shop-body {
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 0 14px 8px;
  scrollbar-width: none;
}

.shop-body::-webkit-scrollbar { display: none; }

.wallet-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid rgba(244, 187, 85, 0.16);
  border-radius: 12px;
  background: rgba(244, 187, 85, 0.055);
  color: #cbb895;
  font-size: 7.5px;
  font-weight: 800;
}

.wallet-strip strong {
  display: flex;
  align-items: center;
